UPDATE ifj_maintenance_lease
SET last_completed_at = CURRENT_TIMESTAMP(3),
    last_success = TRUE,
    last_failure_code = NULL,
    update_time = CURRENT_TIMESTAMP(3)
WHERE lease_name = #{leaseName}
  AND lease_owner = #{leaseOwner}
  AND lease_token = #{leaseToken}
  AND fence_token = #{fenceToken}

UPDATE ifj_maintenance_lease
SET last_completed_at = strftime('%Y-%m-%d %H:%M:%f','now'),
    last_success = TRUE,
    last_failure_code = NULL,
    update_time = strftime('%Y-%m-%d %H:%M:%f','now')
WHERE lease_name = #{leaseName}
  AND lease_owner = #{leaseOwner}
  AND lease_token = #{leaseToken}
  AND fence_token = #{fenceToken}

UPDATE ifj_maintenance_lease
SET last_completed_at = CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3)),
    last_success = 1,
    last_failure_code = NULL,
    update_time = CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3))
WHERE lease_name = #{leaseName}
  AND lease_owner = #{leaseOwner}
  AND lease_token = #{leaseToken}
  AND fence_token = #{fenceToken}

UPDATE ifj_maintenance_lease
SET last_completed_at = SYSUTCDATETIME(),
