    last_failure_code = NULL,
    update_time = SYSUTCDATETIME()
WHERE lease_name = #{leaseName}
  AND lease_owner = #{leaseOwner}
  AND lease_token = #{leaseToken}
  AND fence_token = #{fenceToken}

